script_content = '''import sys, json
from pathlib import Path

SKILL_DIR = Path("/workspace/skills/state-customer-support")
sys.path.insert(0, str(SKILL_DIR))

from domain_meta import DEFAULT_NOW, ENV_CLASS, ENV_DATA_CLASS, SAVE_MAP
from tools import WRITE_TOOL_NAMES

# --- session codec (from cli.py) ---
def _dec(o):
    if isinstance(o, dict):
        if set(o.keys()) == {"__set__"}:
            return {_dec(x) for x in o["__set__"]}
        if set(o.keys()) == {"__tuple__"}:
            return tuple(_dec(x) for x in o["__tuple__"])
        return {k: _dec(v) for k, v in o.items()}
    if isinstance(o, list):
        return [_dec(x) for x in o]
    return o

def _enc(o):
    if isinstance(o, set):
        return {"__set__": [_enc(x) for x in o]}
    if isinstance(o, tuple):
        return {"__tuple__": [_enc(x) for x in o]}
    if isinstance(o, dict):
        return {k: _enc(v) for k, v in o.items()}
    if isinstance(o, list):
        return [_enc(x) for x in o]
    return o

ws = SKILL_DIR / ".state"
ws.mkdir(parents=True, exist_ok=True)
state_path = ws / "state.json"
session_path = ws / "session.json"

def call_tool(tool_name, params):
    env_data = ENV_DATA_CLASS.load(state_path)
    env = ENV_CLASS(env_data, now=DEFAULT_NOW)
    if session_path.exists():
        for k, v in _dec(json.loads(session_path.read_text())).items():
            setattr(env, k, v)
    handler = env.tool_handlers.get(tool_name)
    if handler is None:
        return {"error": f"Unknown tool '{tool_name}'"}
    try:
        result = handler(params)
    except Exception as e:
        return {"error": f"{type(e).__name__}: {e}"}
    rebuilt = ENV_DATA_CLASS(**{field: list(getattr(env, attr).values()) for field, attr in SAVE_MAP.items()})
    rebuilt.save(state_path)
    sess_out = {k: v for k, v in vars(env).items() if k.startswith("_")}
    session_path.write_text(json.dumps(_enc(sess_out), indent=2))
    return {"tool": tool_name, "is_write": tool_name in WRITE_TOOL_NAMES, "result": result}

results = {}

# Step 1: Get warranty status for ITEM-4D9AFC
results["warranty_status"] = call_tool("get_warranty_status", {"item_id": "ITEM-4D9AFC"})

