# Write results
with open("/workspace/tool_results.json", "w") as f:
    json.dump(results, f, indent=2, default=str)

print("SUCCESS: " + str(len(results)) + " tool calls completed")
for k, v in results.items():
    if "error" in v:
        print(f"  {k}: ERROR - {v['error']}")
    else:
        print(f"  {k}: OK")
'''
